// Embedded stylesheet and brand fonts for the server-rendered consent page.
// Generated by `aube run -F dashboard build:consent-page` from
// client/dashboard/src/consent-page; never hand-edit the assets. The build
// compiles the dashboard design system against consent_template.html, so the
// page uses the same tokens, type scale and utilities as the dashboard rather
// than a parallel hand-written stylesheet that drifts.

package mcp

import (
	"embed"
	"fmt"
	"html/template"
	"io/fs"
	"net/http"
	"path"
	"strings"

	"github.com/go-chi/chi/v5"

	"github.com/speakeasy-api/gram/server/internal/oops"
)

//go:embed consent_page_assets
var consentPageAssets embed.FS

// consentPageStyles is the compiled stylesheet, inlined into the template's
// <style> block. Inlined rather than linked because the consent page is served
// Cache-Control: no-store — a separate request would buy no caching and only
// add a round-trip before first paint. template.CSS because the content is a
// build artifact, not user input.
var consentPageStyles = func() template.CSS {
	data, err := consentPageAssets.ReadFile("consent_page_assets/consent-page.css")
	if err != nil {
		panic(fmt.Sprintf("read embedded consent page stylesheet: %v", err))
	}
	// #nosec G203 -- the stylesheet is a build artifact compiled from the
	// dashboard design system and embedded at compile time; no request data
	// reaches it.
	return template.CSS(data)
}()

// ServeConsentFont serves one embedded brand font. Mounted at
// `GET /mcp/consent-fonts/{file}`, which is also the build's `base` and so
// the prefix the stylesheet's @font-face urls point at. Fonts are separate
// immutable responses rather than data: URIs inlined into a stylesheet that
// renders uncached on every consent view. File names are content-hashed by the build,
// so the response is immutable; an unknown name is a stale URL.
func (s *Service) ServeConsentFont(w http.ResponseWriter, r *http.Request) error {
	name := chi.URLParam(r, "file")
	// The name indexes a fixed embedded directory, so reject anything that
	// could escape it rather than relying on the FS to refuse.
	if name == "" || !strings.HasSuffix(name, ".woff2") || name != path.Base(name) {
		w.WriteHeader(http.StatusNotFound)
		return nil
	}

	data, err := consentPageAssets.ReadFile("consent_page_assets/" + name)
	if err != nil {
		w.WriteHeader(http.StatusNotFound)
		return nil
	}

	w.Header().Set("Content-Type", "font/woff2")
	w.Header().Set("Cache-Control", "public, max-age=31536000, immutable")
	w.WriteHeader(http.StatusOK)
	if _, err := w.Write(data); err != nil {
		return oops.E(oops.CodeUnexpected, err, "write consent font response").LogError(r.Context(), s.logger)
	}
	return nil
}

// consentPageFontNames lists the embedded font files, for the test that keeps
// the stylesheet's @font-face urls and the embedded assets in step.
func consentPageFontNames() ([]string, error) {
	entries, err := fs.ReadDir(consentPageAssets, "consent_page_assets")
	if err != nil {
		return nil, fmt.Errorf("read embedded consent page assets: %w", err)
	}
	names := make([]string, 0, len(entries))
	for _, e := range entries {
		if strings.HasSuffix(e.Name(), ".woff2") {
			names = append(names, e.Name())
		}
	}
	return names, nil
}
